mapper.select:
select count(distinct vma.id) FROM virtual_warehouse_allocation_detail vmad inner JOIN virtual_warehouse_allocation vma on vma.id = vmad.main_id and vma.is_deleted = false where vmad.is_deleted = false
and vma.status = #{params.status}
${params.permissionSql}

mapper.sql:
SELECT vma.id, vmad.id as detailId, vma.code, vma.status, vma.type, vmad.sku_id as skuId, vmad.sku_no as skuNo, vmad.product_name as productName, vmad.warehouse_id as warehouseId, vmad.warehouse_name, vmad.from_virtual_warehouse_id as fromVirtualWarehouseId, vmad.from_virtual_warehouse_name, vmad.qty, vmad.to_virtual_warehouse_id as toVirtualWarehouseId, vmad.to_virtual_warehouse_name, vmad.finish_description, vma.invalid_description, vmad.sync_status as syncStatus, vmad.create_user_id, vmad.create_user_name, vmad.create_time, vmad.update_user_id, vmad.update_user_name, vmad.update_time, vmad.third_code, vmad.sys_type, vmad.sys_type_name FROM virtual_warehouse_allocation_detail vmad inner JOIN virtual_warehouse_allocation vma on vma.id = vmad.main_id and vma.is_deleted = false where ${params.sqlMap.default} and vmad.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
vma.id,vmad.id desc
